<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import type {GeoJsonObject} from 'geojson';
import {Search,Star,MapPin,Navigation,Plus,Layers,LocateFixed,Download,Upload} from 'lucide-vue-next';
import geometry from '../data/campus-geometry.json';
import {saveFile} from '../services/files';
import {campusCenters,sourcePlaces,placeCategories,readMapData,saveMapData,filterPlaces,validPlace,navigationUrl,type Campus,type CampusPlace,type PlaceCategory} from '../services/campus-map';
const initial=readMapData(),personal=ref(initial.places),favorites=ref(initial.favorites),campus=ref<Campus>('east'),query=ref(''),category=ref('all'),selected=ref<CampusPlace>(),message=ref(''),online=ref(false);
const element=ref<HTMLElement>(),name=ref(''),note=ref(''),newCategory=ref<PlaceCategory>('life'),draft=ref<{lat:number;lng:number}>(),adding=ref(false),file=ref<HTMLInputElement>();
const places=computed(()=>[...personal.value,...sourcePlaces]),filtered=computed(()=>filterPlaces(places.value,campus.value,query.value,category.value,favorites.value));
let map:L.Map|undefined,markers:L.LayerGroup|undefined,tiles:L.TileLayer|undefined,resize:ResizeObserver|undefined;
function persist(){try{saveMapData(personal.value,favorites.value);message.value=''}catch{message.value='保存失败，请检查设备存储空间';return false}return true}
function renderMarkers(){if(!map||!markers)return;markers.clearLayers();for(const p of filtered.value){const dot=L.circleMarker([p.lat,p.lng],{radius:8,color:'#fff',weight:2,fillColor:p.source==='personal'?'#6f62c6':'#678f88',fillOpacity:1}).addTo(markers);const title=document.createElement('span');title.textContent=p.name;dot.bindTooltip(title).on('click',()=>choose(p))}}
function choose(p:CampusPlace){selected.value=p;map?.setView([p.lat,p.lng],18,{animate:false})}
function recenter(){const c=campusCenters[campus.value];map?.setView([c.lat,c.lng],16,{animate:false})}
function favorite(p:CampusPlace){const before=[...favorites.value];favorites.value=favorites.value.includes(p.id)?favorites.value.filter(id=>id!==p.id):[...favorites.value,p.id];if(!persist())favorites.value=before}
function remove(p:CampusPlace){const before=personal.value;personal.value=personal.value.filter(x=>x.id!==p.id);if(persist())selected.value=undefined;else personal.value=before}
function add(){if(!draft.value||!name.value.trim())return;const p:CampusPlace={id:crypto.randomUUID(),name:name.value.trim(),...draft.value,category:newCategory.value,campus:campus.value,source:'personal',note:note.value.trim()};if(!validPlace(p)){message.value='请选择校园附近位置，并检查地点名称';return}if(personal.value.length>=100){message.value='最多保存100个个人地点';return}personal.value=[...personal.value,p];if(persist()){draft.value=undefined;adding.value=false;name.value='';note.value='';choose(p)}else personal.value=personal.value.filter(x=>x.id!==p.id)}
function pickLocation(point:L.LatLng){if(point.lat<36.55||point.lat>36.60||point.lng<114.47||point.lng>114.53){message.value='请在邯郸学院附近选点';return}draft.value={lat:point.lat,lng:point.lng};selected.value=undefined}
function toggleTiles(){online.value=!online.value;if(!map)return;if(online.value){tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors',updateWhenIdle:true});tiles.on('tileerror',()=>{message.value='在线底图暂不可用，仍可查看离线道路和已保存地点'});tiles.addTo(map).bringToBack()}else{tiles?.remove();tiles=undefined;message.value=''}}
async function exportPlaces(){try{await saveFile('handan-map-places.json',JSON.stringify({version:1,places:personal.value,favorites:favorites.value},null,2))}catch{message.value='导出未完成，请重试'}}
async function importPlaces(event:Event){const input=event.target as HTMLInputElement;const f=input.files?.[0];try{if(!f)return;if(f.size>256000)throw Error();const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.places)||!data.places.every(validPlace))throw Error();const merged=new Map(personal.value.map(p=>[p.id,p]));for(const p of data.places as CampusPlace[])if(!merged.has(p.id))merged.set(p.id,p);if(merged.size>100)throw Error();const before=personal.value,oldFavorites=favorites.value;personal.value=[...merged.values()];const known=new Set([...personal.value,...sourcePlaces].map(p=>p.id));favorites.value=[...new Set([...favorites.value,...(Array.isArray(data.favorites)?data.favorites.filter((id:unknown)=>typeof id==='string'&&known.has(id)):[])])];if(!persist()){personal.value=before;favorites.value=oldFavorites}else message.value='地点与收藏已导入，原有地点保留'}catch{message.value='文件无效或地点过多，原有地点已保留'}finally{input.value=''}}
watch(campus,()=>{selected.value=undefined;draft.value=undefined;recenter();renderMarkers()});watch(filtered,renderMarkers);
onMounted(async()=>{await nextTick();if(!element.value)return;map=L.map(element.value,{zoomControl:false,minZoom:14,maxZoom:19,maxBounds:[[36.55,114.47],[36.60,114.53]],maxBoundsViscosity:1,attributionControl:true});
 map.attributionControl.setPrefix(false);map.attributionControl.addAttribution('© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors · 2026-11-08');
 L.geoJSON(geometry as GeoJsonObject,{style:feature=>({color:feature?.properties?.kind==='road'?'#fff':feature?.properties?.kind==='campus'?'#a3c5ad':'#c2cad5',weight:feature?.properties?.kind==='road'?6:1.5,fillColor:feature?.properties?.kind==='campus'?'#e0ecdf':'#e0e5ec',fillOpacity:0.75})}).addTo(map);
 markers=L.layerGroup().addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);map.on('click',e=>{if(adding.value)pickLocation(e.latlng)});map.on('contextmenu',e=>{adding.value=true;pickLocation(e.latlng)});recenter();renderMarkers();resize=new ResizeObserver(()=>map?.invalidateSize());resize.observe(element.value);
});
onUnmounted(()=>{resize?.disconnect();map?.remove();map=undefined});
</script>
<template>
 <div class="campus-map"><span class="micro-label">探索校园</span><h2>校园地图</h2>
  <div class="map-campus"><button v-for="(c,id) in campusCenters" :key="id" :class="{active:campus===id}" @click="campus=id">{{c.name}}</button></div>
  <label class="map-search"><Search :size="17"/><input v-model="query" aria-label="搜索校园地点" placeholder="搜索楼名或自己保存的地点"/></label>
  <div class="map-categories" aria-label="地点分类"><button :class="{active:category==='all'}" @click="category='all'">全部</button><button :class="{active:category==='favorite'}" @click="category='favorite'">收藏</button><button v-for="(label,id) in placeCategories" :key="id" :class="{active:category===id}" @click="category=id">{{label}}</button></div>
  <div ref="element" class="map-canvas" aria-label="可缩放的校园地图"/>
  <div class="map-tools"><button @click="recenter"><LocateFixed :size="16"/>回到校区</button><button :aria-pressed="online" @click="toggleTiles"><Layers :size="16"/>{{online?'离线底图':'在线底图'}}</button><button :aria-pressed="adding" @click="adding=!adding;draft=undefined"><Plus :size="16"/>{{adding?'取消选点':'添加地点'}}</button></div>
  <p class="map-note">{{adding?'点击或长按地图，标记你常用的地点。':campusCenters[campus].note}}</p>
  <p v-if="message" class="map-message" role="status">{{message}}</p>
  <form v-if="draft" class="map-detail" @submit.prevent="add"><h3>添加个人地点</h3><label>名称<input v-model="name" required maxlength="60" placeholder="例如：宿舍饮水机"/></label><label>类别<select v-model="newCategory"><option v-for="(label,id) in placeCategories" :key="id" :value="id">{{label}}</option></select></label><label>备注<input v-model="note" maxlength="200" placeholder="例如：一楼大厅右侧"/></label><div class="map-actions"><button type="button" class="secondary" @click="draft=undefined">取消</button><button class="primary">保存地点</button></div></form>
  <article v-if="selected" class="map-detail"><div class="map-detail-heading"><h3>{{selected.name}}</h3><button class="icon-button" :aria-label="favorites.includes(selected.id)?'取消收藏':'收藏地点'" @click="favorite(selected)"><Star :size="20" :fill="favorites.includes(selected.id)?'currentColor':'none'"/></button></div><p>{{selected.note||'个人保存地点'}}</p><div class="map-actions"><button v-if="selected.source==='personal'" class="text-button danger" @click="remove(selected)">删除地点</button><a class="secondary" :href="navigationUrl(selected)" target="_blank" rel="noopener"><Navigation :size="16"/>步行路线</a></div></article>
  <div class="map-list"><button v-for="p in filtered" :key="p.id" @click="choose(p)"><MapPin :size="17"/><span><strong>{{p.name}}</strong><small>{{p.source==='personal'?'我的地点':'图源旧称 · 待核对'}}</small></span><Star v-if="favorites.includes(p.id)" :size="14"/></button><p v-if="!filtered.length" class="map-empty">{{query?'没有找到匹配地点':category==='favorite'?'还没有收藏地点':'此分类暂未收录地点'}}。可以长按地图添加。</p></div>
  <details class="map-about"><summary>地图说明与地点备份</summary><p>底图采用公开道路和建筑轮廓，可离线查看。图源名称可能滞后，校区中心不是校门；不提供虚构的楼宇坐标或校内最短路线。在线底图需要网络，步行路线交由地图服务查询，请以现场通行情况为准。</p><div class="map-tools"><button @click="exportPlaces"><Download :size="16"/>导出地点</button><button @click="file?.click()"><Upload :size="16"/>导入地点</button></div><input ref="file" type="file" accept="application/json,.json" hidden @change="importPlaces"/></details>
 </div>
</template>
<style scoped>
.campus-map{padding-top:8px}.campus-map h2{margin:8px 0 16px}.map-campus{display:flex;gap:6px;background:var(--color-bg);padding:4px;border-radius:12px}.map-campus button{flex:1;border:0;background:transparent;border-radius:9px;min-height:39px;font-size:13px;color:var(--color-muted)}.map-campus .active{background:var(--color-surface,#fff);font-weight:650;color:var(--color-text)}.map-search{display:flex;align-items:center;gap:9px;margin:14px 0 10px;padding:0 12px;background:var(--color-bg);border-radius:12px;min-height:44px;color:var(--color-muted)}.map-search input{width:100%;min-width:0;background:transparent;border:0;outline:0;font-size:13px;color:var(--color-text)}.map-categories{display:flex;gap:7px;overflow-x:auto;padding-bottom:12px}.map-categories button{border:1px solid var(--color-border,#e3e6ed);background:var(--color-surface,#fff);border-radius:20px;min-height:34px;padding:6px 12px;font-size:11px;white-space:nowrap;color:var(--color-muted)}.map-categories .active{background:var(--color-primary);color:#fff;border-color:transparent}.map-canvas{height:clamp(280px,43dvh,440px);background:#eef0e9;border:1px solid #e0e6de;border-radius:17px;isolation:isolate;z-index:0}.map-tools{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.map-tools button{display:flex;align-items:center;justify-content:center;gap:5px;flex:1;min-height:40px;white-space:nowrap;padding:7px;border:1px solid var(--color-border,#e3e6ed);border-radius:11px;background:var(--color-surface,#fff);font-size:11px;color:var(--color-text)}.map-note,.map-about p{font-size:11px;color:var(--color-muted);line-height:1.65}.map-message{padding:10px;background:var(--color-tint);border-radius:10px;font-size:12px}.map-detail{padding:16px;border:1px solid var(--color-border,#e3e6ed);border-radius:15px;margin:14px 0}.map-detail h3{font-size:15px;margin:0;overflow-wrap:anywhere}.map-detail p{font-size:12px;color:var(--color-muted)}.map-detail label{display:block;font-size:12px;margin-top:12px;color:var(--color-muted)}.map-detail input,.map-detail select{display:block;width:100%;min-height:42px;font:inherit;border:1px solid var(--color-border,#e3e6ed);background:var(--color-surface,#fff);border-radius:9px;padding:8px;margin-top:5px;color:var(--color-text)}.map-actions,.map-detail-heading{display:flex;justify-content:space-between;align-items:center;gap:10px}.map-actions{margin-top:14px;justify-content:flex-end}.map-actions a{display:flex;align-items:center;gap:6px;text-decoration:none;font-size:12px}.map-list button{display:flex;align-items:center;text-align:left;gap:10px;width:100%;border:0;border-bottom:1px solid var(--color-border,#e3e6ed);background:transparent;padding:14px 4px;color:var(--color-text)}.map-list span{flex:1;min-width:0}.map-list strong{font-size:13px;overflow-wrap:anywhere}.map-list small{display:block;font-size:10px;color:var(--color-muted);margin-top:5px}.map-empty{padding:18px 6px;font-size:12px;color:var(--color-muted);text-align:center;line-height:1.7}.map-about{margin-top:18px;font-size:12px}.map-about summary{padding:10px 0;cursor:pointer}
</style>
